function expoIn(){const E=v3.env,L=E&&E.pubLum;return L>0?Math.max(0.8,Math.min(40,0.66/Math.pow(Math.max(L,2e-4),0.85))):(isDark()?1.2:0.95);}
function expoOut(){return isDark()?(v3.mode==="walk"?4:4.5):0.95;} // v noci zhora oko trochu prispôsobené tme (vidno obrysy záhrady)
