    v3.hemi.intensity=0.56;v3.hemiBase=[[0.992,0.984,0.969],[0.647,0.616,0.557]];S.background=new T.Color(0xcfe2f0);
    v3.wallMat.emissive.set(0x1a1a19);v3.ceil.children.forEach(m=>m.material.emissive.set(0x353432));for(const k in v3.dm){const m=v3.dm[k];if(m.emissive)m.emissive.set(+k===DOORW?0x181818:0);}
