  {const ms=document.getElementById('lmonth');ms.innerHTML="január,február,marec,apríl,máj,jún,júl,august,september,október,november,december".split(",").map((n,i)=>`<option value="${i+1}">${n}</option>`).join("");ms.value=LS.month;ms.onchange=()=>{LS.month=+ms.value;keep();applyLighting();};}
