  window.__moving=v3.mode==="walk"&&(v3.keys.size>0||!!v3.go);
  if(v3.mark&&v3.mark.visible){const a=(performance.now()-(v3.markT||0))/1000;if(!v3.go&&a>0.6){v3.mark.material.opacity=Math.max(0,0.85-(a-0.6)*2);if(a>1.1&&!v3.hov)v3.mark.visible=false;}}
